Facade: Java Code Example - Facade Class
// The Facade class provides a simple interface to the
// complex logic of one or several subsystems. The Facade
// delegates the client requests to the appropriate objects
// within the subsystem and is also responsible for managing
// their lifecycle.
public
class
VideoConversionFacade
{
public
VideoFile
convert
(String filename, String format)
{
System.out.println(
"VideoConversionFacade: "
+
"conversion started."
);
VideoFile
file
=
new
VideoFile
(filename);
Codec
sourceCodec
=
CodecFactory.extract(file);
Codec destinationCodec;
if
(format.equals(
"mp4"
)) {
destinationCodec =
new
MPEG4CompressionCodec
();
}
else
{
destinationCodec =
new
OggCompressionCodec
();
}
VideoFile
buffer
=
BitrateReader.read(file,
sourceCodec);
VideoFile
result
=
BitrateReader.convert(buffer,
destinationCodec);
result =
new
AudioMixer
().fix(result);
System.out.println(
"VideoConversionFacade: "
+
"conversion completed."
);
return
result;
}
