import
java.awt.*;
// The flyweight class contains a portion of the state of a
// tree. These fields store values that are unique for each
// particular tree type. You will not find here the tree
// coordinates. But the texture and colors shared between
// many trees are here. Since this data is usually BIG, you
// would waste a lot of memory by keeping it in each tree
// object. Instead, we extract texture, color, and other
// repeating data into a separate object (TreeType).
public
class
TreeType
{
private
String name;
private
Color color;
private
String texture;
public
TreeType
(String name, Color color, String texture)
{
this
.name = name;
this
.color = color;
this
.texture = texture;
}
public
String
getName
()
{
return
name; }
public
Color
getColor
()
{
return
color; }
public
String
getTexture
()
{
return
texture; }
public
void
draw
(Graphics g,
int
x,
int
y)
{
// Draw the tree on canvas at position (x, y)
g.setColor(Color.BLACK);
g.fillRect(x -
1
, y,
3
,
5
);
g.setColor(color);
g.fillOval(x -
5
, y -
10
,
10
,
10
);
}
