private
static
List<TreeType> treeTypes =
new
ArrayList
<>();
public
static
TreeType
getTreeType
(String name,
Color color,
String texture)
{
for
(TreeType type: treeTypes) {
if
(type.getName().equals(name) &&
type.getColor().equals(color) &&
type.getTexture().equals(texture)) {
return
type;
}
TreeType
type
=
new
TreeType
(name, color, texture);
treeTypes.add(type);
return
type;
}
