import
java.util.List;
// The GUI class, which used to work directly with a
// service object, stays unchanged as long as it works
// with the service object through an interface. We can
// safely pass a proxy object instead of a real service
// object since they both implement the same interface.
public
class
YouTubeManager
{
private
ThirdPartyYouTubeLib service;
public
YouTubeManager
(ThirdPartyYouTubeLib service)
{
this
.service = service;
}
public
void
renderVideoPage
(String id)
{
Video
info
=
service.getVideoInfo(id);
System.out.println(
"Rendering video page: "
+
info.getTitle());
}
public
void
renderListPanel
()
{
List<Video> list = service.listVideos();
System.out.println(
"Rendering video list: "
+
list.size() +
" videos"
);
}
public
void
reactOnUserInput
(String id)
{
renderListPanel();
renderVideoPage(id);
}
